<form data-branch-schedule method="post" action="/admin/branches/hours/create" class="admin-form branch-hours-form"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($branch->id) ?>"><div class="admin-form-grid"><label class="admin-field branch-hours-day"><span>Día</span><select name="iso_weekday" required><option value="">Selecciona un día</option><?php foreach ($days as $number => $day): ?><option value="<?= e($number) ?>"><?= e($day) ?></option><?php endforeach ?></select></label><label class="admin-field"><span>Apertura</span><input type="time" name="opens_at" required></label><label class="admin-field"><span>Cierre</span><input type="time" name="closes_at" required></label><label class="admin-check branch-hours-crosses"><input type="checkbox" name="crosses_midnight" value="1"><span><strong>Termina al día siguiente</strong><small>Por ejemplo, de 20:00 a 02:00.</small></span></label></div><button class="admin-secondary-button" type="submit">Agregar intervalo</button></form>
</section>
